func adoptValues() map[string]any {
	return map[string]any{
		"name":        "Extractor.Perfion",
		"topic":       "product-export",
		"contract":    "ExportEvent",
		"appId":       "product-distribution-extractor-perfion",
		"projectName": "Extractor.Perfion",
		"port":        "perfion-extractor-source",
	}
}

func adoptOpts(srv *httptest.Server, dir string) AdoptOptions {
	return AdoptOptions{
		CreateOptions: CreateOptions{
			Template:      "extractor",
			Version:       "v1.2.3",
			SetValues:     adoptValues(),
			NoInput:       true,
			HTTP:          srv.Client(),
			Owner:         "o",
			Repo:          "r",
			GitHubBaseURL: srv.URL,
		},
		ProjectDir: dir,
	}
}

func readAdoptedRecord(t *testing.T, dir string) Scaffold {
	t.Helper()
	s, err := LoadScaffold(filepath.Join(dir, filepath.FromSlash(ScaffoldRelPath)))
	if err != nil {
		t.Fatalf("load scaffold: %v", err)
	}
	return *s
}

func TestAdoptWritesRecord(t *testing.T) {
	srv := newAdoptServer(t, "v1.2.3")
	defer srv.Close()

	dir := t.TempDir()
	if err := os.WriteFile(filepath.Join(dir, "Extractor.Perfion.csproj"), []byte("<Project/>"), 0o644); err != nil {
		t.Fatal(err)
	}
	var stdout, stderr bytes.Buffer
	opts := adoptOpts(srv, dir)
	opts.Stdout = &stdout
	opts.Stderr = &stderr

	if err := Adopt(context.Background(), opts); err != nil {
		t.Fatalf("Adopt: %v", err)
	}

	got := readAdoptedRecord(t, dir)
	if got.SchemaVersion != ScaffoldSchemaVersion {
		t.Errorf("SchemaVersion = %d", got.SchemaVersion)
	}
	if got.Template != "extractor" {
		t.Errorf("Template = %q", got.Template)
	}
	if got.Owner != "o" || got.Repo != "r" {
		t.Errorf("Owner/Repo = %q/%q", got.Owner, got.Repo)
	}
	if got.Version != "v1.2.3" {
		t.Errorf("Version = %q", got.Version)
	}
	if got.BlockKind != BlockKindExtractor || got.DataFlow != "in" {
		t.Errorf("BlockKind/DataFlow = %q/%q", got.BlockKind, got.DataFlow)
	}
	if got.Values["name"] != "Extractor.Perfion" {
		t.Errorf("values[name] = %v", got.Values["name"])
	}
	if got.Values["pubsub"] != "pubsub" {
		t.Errorf("values[pubsub] = %v (default should layer in)", got.Values["pubsub"])
	}
	if stdout.Len() != 0 {
		t.Errorf("stdout should be empty on write, got %q", stdout.String())
	}
	if !strings.Contains(stderr.String(), "adopted") {
		t.Errorf("stderr should carry the report, got %q", stderr.String())
	}
	if strings.Contains(stderr.String(), "no Extractor.Perfion.csproj") {
		t.Errorf("matching csproj should produce no projectName drift warning, got %q", stderr.String())
	}
}

